const audio = Inputs.audio;
const mimeType = String(Inputs.mimeType || 'audio/mpeg');
if (!audio) return;

// A finished file (audio/wav, audio/mpeg, audio/ogg ...) plays exactly as it came.
let url = 'data:' + mimeType + ';base64,' + audio;

// Only raw 16-bit samples need a WAV header around them.
if (/^audio\/(l16|pcm)/i.test(mimeType)) {
  const rate = Number((/rate=(\d+)/i.exec(mimeType) || [])[1]) || 24000;
  const samples = Uint8Array.from(atob(audio), (c) => c.charCodeAt(0));
  const wav = new DataView(new ArrayBuffer(44 + samples.length));
  const text = (at, s) => [...s].forEach((ch, i) => wav.setUint8(at + i, ch.charCodeAt(0)));
  text(0, 'RIFF'); wav.setUint32(4, 36 + samples.length, true); text(8, 'WAVE');
  text(12, 'fmt '); wav.setUint32(16, 16, true); wav.setUint16(20, 1, true); wav.setUint16(22, 1, true);
  wav.setUint32(24, rate, true); wav.setUint32(28, rate * 2, true); wav.setUint16(32, 2, true); wav.setUint16(34, 16, true);
  text(36, 'data'); wav.setUint32(40, samples.length, true);
  new Uint8Array(wav.buffer, 44).set(samples);
  let bytes = '';
  new Uint8Array(wav.buffer).forEach((b) => (bytes += String.fromCharCode(b)));
  url = 'data:audio/wav;base64,' + btoa(bytes);
}

await new Audio(url).play();

const key = Inputs.key;
const text = String(Inputs.text || '');
if (!key || !text) return;

const model = 'gemini-3.8-flash-tts';
const response = await fetch('https://generativelanguage.googleapis.com/v1beta/models/' + model + ':generateContent', {
  method: 'POST',
  headers: { 'content-type': 'application/json', 'x-goog-api-key': key },
  body: JSON.stringify({
    contents: [{ parts: [{ text }] }],
    generationConfig: {
      responseModalities: ['AUDIO'],
      speechConfig: { voiceConfig: { prebuiltVoiceConfig: { voiceName: 'Kore' } } }
    }
  })
});
const body = await response.json();
if (!response.ok) throw new Error((body.error && body.error.message) || 'Text-to-speech refused the request');

const part = body.candidates && body.candidates[0] && body.candidates[0].content && body.candidates[0].content.parts[0];
const audio = part && part.inlineData;
if (!audio || !audio.data) throw new Error('Text-to-speech sent no audio');

// Pass the audio through exactly as it came: do not decode it, re-encode it or add a header here.
Outputs.audio = audio.data;
Outputs.mimeType = audio.mimeType;
